<?php

declare(strict_types=1);

require_once __DIR__ . '/Database.php';
require_once __DIR__ . '/Auth.php';
require_once __DIR__ . '/AppNavigation.php';
require_once __DIR__ . '/AccessPolicy.php';
require_once __DIR__ . '/ProductionContext.php';
require_once __DIR__ . '/VolunteerCoverageService.php';

final class ProductionWorkspaceExperience
{
    private const ROUTE = '/production';

    public static function handles(string $route): bool{return $route === self::ROUTE;}

    public static function render(string $basePath): never
    {
        Auth::startSession();
        $db = Database::connect(dirname(__DIR__));
        $user = Auth::currentUser($db);
        if (!$user) self::redirect(($basePath ?: '') . '/login');
        $_SESSION['production_context_csrf'] ??= bin2hex(random_bytes(24));
        $productions = ProductionContext::activeProductions($db, $user);$selected = ProductionContext::selected($db, $user);$workspaces = self::workspaceMetrics($db, $productions);self::page($basePath, $user, $workspaces, $selected);
    }

    private static function workspaceMetrics(PDO $db, array $productions): array
    {
        if (!$productions) return [];$ids = array_map(static fn(array $row): int => (int)$row['id'], $productions);$placeholders = implode(',', array_fill(0, count($ids), '?'));$metrics = [];
        foreach ($productions as $production) {$id = (int)$production['id'];$metrics[$id] = $production + ['member_count'=>0,'schedule_count'=>0,'channel_count'=>0,'open_volunteer_slots'=>0];}
        $members = $db->prepare("SELECT pm.production_id, COUNT(DISTINCT pm.user_id) AS total FROM production_memberships pm JOIN users u ON u.id=pm.user_id AND u.active=1 AND u.account_status<>'disabled' WHERE pm.status='active' AND pm.production_id IN ($placeholders) GROUP BY pm.production_id");$members->execute($ids);foreach ($members->fetchAll() as $row) $metrics[(int)$row['production_id']]['member_count'] = (int)$row['total'];
        $schedule = $db->prepare("SELECT production_id, COUNT(*) AS total FROM schedule_items WHERE status='active' AND production_id IN ($placeholders) GROUP BY production_id");$schedule->execute($ids);foreach ($schedule->fetchAll() as $row) $metrics[(int)$row['production_id']]['schedule_count'] = (int)$row['total'];
        $channels = $db->prepare("SELECT production_id, COUNT(*) AS total FROM channels WHERE archived_at IS NULL AND production_id IN ($placeholders) GROUP BY production_id");$channels->execute($ids);foreach ($channels->fetchAll() as $row) $metrics[(int)$row['production_id']]['channel_count'] = (int)$row['total'];
        $shiftStmt=$db->prepare("SELECT id,production_id,required_slots FROM volunteer_shifts WHERE starts_at>=NOW() AND production_id IN ($placeholders) ORDER BY production_id,starts_at,id");$shiftStmt->execute($ids);foreach($shiftStmt->fetchAll() as $shift){$productionId=(int)$shift['production_id'];$open=max((int)$shift['required_slots']-VolunteerCoverageService::eligibleLiveSignupCount($db,(int)$shift['id']),0);$metrics[$productionId]['open_volunteer_slots']+=$open;}
        return array_values($metrics);
    }

    private static function page(string $basePath,array $user,array $workspaces,?array $selected):never
    {
        $url=static fn(string $path):string=>($basePath?:'').$path;$esc=static fn(string $value):string=>htmlspecialchars($value,ENT_QUOTES,'UTF-8');$staff=AccessPolicy::canManageProduction($user);$scheduleManager=AccessPolicy::canManageSchedule($user);$flash=$_SESSION['production_context_flash']??null;unset($_SESSION['production_context_flash']);header('Content-Type: text/html; charset=utf-8');?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#a6192e"><title>Production workspace · CTSMD Connect</title><link rel="stylesheet" href="<?= $url('/assets/css/app.css') ?>"><link rel="stylesheet" href="<?= $url('/assets/css/unified-navigation.css') ?>"><link rel="stylesheet" href="<?= $url('/assets/css/production-workspace.css') ?>"></head><body class="app-body"><div class="unified-shell"><?php AppNavigation::renderSidebar('/production',$basePath,$user);?><main class="unified-main"><?php AppNavigation::renderHeader('Production','Production workspace',$basePath,[['label'=>'Workspace','href'=>'/production','active'=>true],['label'=>'Casting','href'=>'/production/casting','active'=>false],['label'=>'Readiness','href'=>'/production/readiness','active'=>false],['label'=>'Production day','href'=>'/production/day','active'=>false],['label'=>'Schedule','href'=>'/schedule','active'=>false],['label'=>'Attendance','href'=>'/attendance','active'=>false],['label'=>'Resources','href'=>'/resources','active'=>false],['label'=>'Playbill','href'=>'/playbills','active'=>false]]);?><div class="pw-page"><?php if($flash):?><div class="pw-flash <?= $esc($flash['type']) ?>"><?= $esc($flash['message']) ?></div><?php endif;?><section class="pw-hero"><div><small>SHOW WORKSPACE</small><h2>Which production are you working on?</h2><p>Active productions can run at the same time. Choosing one here changes only your current browser session—it does not activate, deactivate, archive, or otherwise change another show.</p></div><?php if($staff):?><a href="<?= $url('/admin/productions') ?>">Manage productions →</a><?php endif;?></section>
        <?php if(!$workspaces):?><section class="pw-empty"><h3>No active productions available.</h3><p><?= $staff?'Activate a production in Productions & seasons to create a workspace.':'Your account is not currently assigned to an active production.' ?></p><?php if($staff):?><a class="button" href="<?= $url('/admin/productions') ?>">Productions & seasons</a><?php endif;?></section><?php else:?><section class="pw-selector" aria-label="Active production workspaces"><?php foreach($workspaces as $workspace):$isSelected=$selected&&(int)$selected['id']===(int)$workspace['id'];?><article class="pw-show<?= $isSelected?' selected':'' ?>"><div class="pw-show-top"><span><?= $isSelected?'WORKING NOW':'ACTIVE SHOW' ?></span><?php if($isSelected):?><b>✓ Selected</b><?php endif;?></div><h3><?= $esc((string)$workspace['title']) ?></h3><p><?= $esc((string)($workspace['season']?:'Season not set')) ?></p><div class="pw-metrics"><span><b><?= (int)$workspace['member_count'] ?></b><small>people</small></span><span><b><?= (int)$workspace['schedule_count'] ?></b><small>active schedule</small></span><span><b><?= (int)$workspace['channel_count'] ?></b><small>channels</small></span><span><b><?= (int)$workspace['open_volunteer_slots'] ?></b><small>upcoming open slots</small></span></div><?php if($isSelected):?><div class="pw-actions"><a class="button" href="<?= $url('/production/day') ?>">Open production day</a><?php if($staff):?><a href="<?= $url('/production/casting') ?>">Casting</a><?php endif;?><a href="<?= $url('/production/readiness') ?>">Readiness</a><a href="<?= $url('/schedule') ?>">Schedule</a><?php if($staff):?><a href="<?= $url('/production/people') ?>">Manage roster</a><?php endif;?></div><?php else:?><form method="post" action="<?= $url('/production/select') ?>"><input type="hidden" name="csrf_token" value="<?= $esc((string)$_SESSION['production_context_csrf']) ?>"><input type="hidden" name="production_id" value="<?= (int)$workspace['id'] ?>"><input type="hidden" name="return_to" value="/production"><button class="button full" type="submit">Work in this show</button></form><?php endif;?></article><?php endforeach;?></section>
        <?php if($selected):?><section class="pw-current"><div><small>CURRENT WORKSPACE</small><h2><?= $esc((string)$selected['title']) ?></h2><p><?= $esc((string)($selected['season']?:'Season not set')) ?> · Everything below opens in this production context.</p></div><span>Active</span></section><div class="pw-modules"><?php if($staff):?><a href="<?= $url('/production/casting') ?>"><i>★</i><b>Casting</b><span>Audition review, role decisions and roster finalization.</span></a><a href="<?= $url('/production/day') ?>"><i>☀</i><b>Production day</b><span>Call sheet, attendance, volunteers and live operations.</span></a><a href="<?= $url('/production/readiness') ?>"><i>◈</i><b>Readiness</b><span>System signals and the production checklist.</span></a><?php endif;?><a href="<?= $url('/schedule') ?>"><i>◷</i><b>Schedule</b><span>Rehearsals, performances, calls and locations.</span></a><a href="<?= $url('/attendance') ?>"><i>✓</i><b>Attendance</b><span><?= $staff?'Take roll, review absences and track participation.':'View relevant calls and report an absence.' ?></span></a><?php if($staff):?><a href="<?= $url('/production/people') ?>"><i>★</i><b>Cast & people</b><span>Students, guardians and production staff.</span></a><?php endif;?><a href="<?= $url('/channels') ?>"><i>#</i><b>Community</b><span>Production channels and announcements.</span></a><a href="<?= $url('/volunteer-shifts') ?>"><i>♡</i><b>Volunteer</b><span>Coverage and opportunities for this show.</span></a><a href="<?= $url('/forms') ?>"><i>✓</i><b>Forms</b><span>Requirements and assigned paperwork.</span></a><a href="<?= $url('/playbills') ?>"><i>▤</i><b>Playbill</b><span>Digital Playbill workspace.</span></a><?php if($scheduleManager):?><a href="<?= $url('/production/notices') ?>"><i>↗</i><b>Production updates</b><span>Review and publish schedule-change communications.</span></a><?php endif;?><?php if($staff):?><a href="<?= $url('/admin/volunteer-shifts') ?>"><i>♟</i><b>Volunteer Operations</b><span>Create shifts and manage staffing.</span></a><?php endif;?></div><?php endif;?><?php endif;?></div></main></div><script src="<?= $url('/assets/js/unified-navigation.js') ?>"></script></body></html><?php exit;
    }
    private static function redirect(string $url):never{header('Location: '.$url,true,303);exit;}
}
